import RNA, random, sys

target = "....((((..(((((..((((..((((.....))))((((((...))).)))))))((((((.((.((.(((((....)).)))))))(((((.((.((.((....))))))(((((.(((....)).))).)))..)).)))))).))))))))(((.(((.(((.((((....))))))))))((((((((...))).)).))).)))))))"
N = len(target)
assert N == 214

# parse pairs
pair = [-1]*N
stack=[]
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop()
        pair[i]=j; pair[j]=i

fc = RNA.fold_compound(target)
_, mfe_target = fc.mfe()

# initialize: G-C at pairs (with some variation), A at unpaired
def init_seq():
    seq = ['A']*N
    for i in range(N):
        if pair[i] > i:
            # choose pair type
            seq[i]='G'; seq[pair[i]]='C'
    return ''.join(seq)

def fold_energy(seq):
    fc = RNA.fold_compound(seq)
    ss, en = fc.mfe()
    return ss, en

def bp_distance(ss, target):
    # use RNA bp distance
    return RNA.bp_distance(ss, target)

def score(seq):
    ss, en = fold_energy(seq)
    d = bp_distance(ss, target)
    # reward: -d (and small energy bonus when matches)
    if d==0:
        return -1000 - en  # solving, prefer lower energy
    return -d

def mutate(seq, nmut):
    s = list(seq)
    for _ in range(nmut):
        i = random.randrange(N)
        s[i] = random.choice('ACGU')
    return ''.join(s)

def targeted_mutate(seq, ss):
    # mutate positions where ss differs from target
    s = list(seq)
    diffs = [i for i in range(N) if ss[i]!=target[i]]
    if not diffs:
        return ''.join(s)
    # pick some diff positions and mutate
    for i in random.sample(diffs, min(len(diffs), random.randint(1,3))):
        # if target says paired but ss unpaired -> strengthen (make G/C matching pair partner)
        # if target unpaired but ss paired -> weaken (mutate to A or mismatch)
        if target[i]=='(' and pair[i]>=0:
            s[i]='G'; s[pair[i]]='C'
        elif target[i]==')' and pair[i]>=0:
            s[i]='C'; s[pair[i]]='G'
        elif target[i]=='.':
            # break possible pairing by making A
            s[i]=random.choice(['A','A','U'])
        else:
            s[i]=random.choice('ACGU')
    return ''.join(s)

