import RNA, random, time, multiprocessing as mp

target = "....((((..(((((..((((..((((.....))))((((((...))).)))))))((((((.((.((.(((((....)).)))))))(((((.((.((.((....))))))(((((.(((....)).))).)))..)).)))))).))))))))(((.(((.(((.((((....))))))))))((((((((...))).)).))).)))))))"
N = len(target)
pair = [-1]*N
stack=[]
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop(); pair[i]=j; pair[j]=i

base = "AUAUCACGAAGCGGCCGAGCGAAACCGUCUUUCGGUGGGAUCUUCGAUACCCCGCUAGGUGGUCGGACAGGGCUAACGAGACCCGUCAUUACAGGCUUGCAACAUCAGUAGCGCGUGCUCACAGGUGAGUGUCGCUCAACGGACCAGCCUGCCGCGCGAAGUCACGAUUCUACUUGGAGCGUACUGGAAGGCAUAAUGCACUCUCCUCGCCGUG"

def fold(seq):
    fc = RNA.fold_compound(seq); ss,en = fc.mfe(); return ss,en

def worker(args):
    seed, tlimit, start = args
    random.seed(seed)
    best = start
    bs, be = fold(best)
    bd = RNA.bp_distance(bs, target)
    t0=time.time()
    it=0
    while time.time()-t0 < tlimit:
        it+=1
        s = list(best)
        diffs = [i for i in range(N) if bs[i]!=target[i]]
        if not diffs:
            break
        r = random.random()
        if r < 0.4:
            # strengthen missing pairs
            missing = [(i,pair[i]) for i in range(N) if target[i]=='(' and pair[i]>i and (bs[i]!='(' or bs[pair[i]]!=')')]
            if missing:
                i,j = random.choice(missing)
                s[i]='G'; s[j]='C'
        elif r < 0.65:
            # break spurious
            st=[]; cur_pairs=[]
            for k,c in enumerate(bs):
                if c=='(': st.append(k)
                elif c==')': cur_pairs.append((st.pop(), k))
            sp_set=set()
            for (i,j) in cur_pairs:
                if pair[i]!=j: sp_set.add(i); sp_set.add(j)
            if sp_set:
                i = random.choice(list(sp_set))
                s[i] = random.choice(['A','A','U'])
        elif r < 0.85:
            if diffs:
                i = random.choice(diffs); s[i]=random.choice('ACGU')
        else:
            # random kick of 2
            for _ in range(2):
                i=random.randrange(N); s[i]=random.choice('ACGU')
        cand=''.join(s)
        cs, ce = fold(cand)
        cd = RNA.bp_distance(cs, target)
        if cd < bd or (cd==bd and random.random()<0.15):
            best=cand; bs=cs; be=ce; bd=cd
    return (bd, best, bs)

if __name__=='__main__':
    nproc = mp.cpu_count()
    print("cpus", nproc, flush=True)
    args = [(s, 180, base) for s in range(nproc)]
    with mp.Pool(nproc) as p:
        results = p.map(worker, args)
    results.sort()
    print("best bd", results[0][0], flush=True)
    print("SEQ", results[0][1], flush=True)
    # also print top 3
    for r in results[:3]:
        print("bd", r[0], r[1], flush=True)
